/**
 * Curated YouTube videos per spot (channel "Mê Câu Cá — Trải Nghiệm
 * Và Chia Sẻ"). Kept in code on purpose: src/data/spots.json is a
 * build-time snapshot regenerated by scripts/fetch-data.mjs, so any
 * field added there would be wiped on the next rebuild.
 */
export interface SpotVideo {
  url: string;
  title: string;
}

const SPOT_VIDEOS: Record<string, SpotVideo> = {
  'ho-cau-bo-ho-550': {
    url: 'https://www.youtube.com/watch?v=BU2SNKjX-hg',
    title: 'Hồ Sơ Bãi: Bờ Hồ 550 — 6 Loài Cá Trong Cùng Một Hồ!',
  },
};

export function spotVideo(slug: string): SpotVideo | undefined {
  return SPOT_VIDEOS[slug];
}
